   292→/// Launch a specific workspace: clone → container → shell RC → tmux → attach.
   293→fn cmd_launch(workspace_arg: Option<&str>, backend: &dyn MultiplexerBackend) -> i32 {
   294→    let st = match state::load() {
   295→        Ok(s) => s,
   296→        Err(e) => {
   297→            error!("{e}");
   298→            return 1;
   299→        }
   300→    };
   301→
   302→    // Resolve workspace: use arg if provided, otherwise auto-detect from cwd
   303→    let entry = if let Some(ws) = workspace_arg {
   304→        match st.resolve_workspace(ws) {
   305→            Some(e) => e,
   306→            None => {
   307→                error!("unknown workspace '{ws}'");
   308→                info!("Configured workspaces:");
   309→                for w in st.all_workspaces() {
   310→                    let id = config::workspace_id(&w.repo, &w.branch);
   311→                    info!("  {id}");
   312→                }
   313→                return 1;
   314→            }
   315→        }
   316→    } else {
   317→        match detect_workspace(&st) {
   318→            Some(e) => {
   319→                let ws_id = config::workspace_id(&e.repo, &e.branch);
   320→                info!("Auto-detected workspace: {ws_id}");
   321→                st.resolve_workspace(&ws_id).unwrap()
   322→            }
   323→            None => {
   324→                error!("could not detect workspace from current directory");
   325→                info!("Usage: dual launch [workspace]");
   326→                return 1;
   327→            }
   328→        }
   329→    };
   330→
   331→    let workspace_root = st.workspace_root();
   332→    let container_name = config::container_name(&entry.repo, &entry.branch);
   333→    let session_name = config::session_name(&entry.repo, &entry.branch);
   334→    debug!(
   335→        repo = %entry.repo,
   336→        branch = %entry.branch,
   337→        "resolved workspace"
   338→    );
   339→
   340→    // Step 1: Resolve workspace directory
   341→    let workspace_dir = if let Some(ref path) = entry.path {
   342→        let dir = PathBuf::from(path);
   343→        if !dir.join(".git").exists() {
   344→            error!(
   345→                "workspace path {} does not contain a git repo",
   346→                dir.display()
   347→            );
   348→            return 1;
   349→        }
   350→        dir
   351→    } else {
   352→        // Try to clone from local main workspace first (fast, hardlinks)
   353→        let target_dir = config::workspace_dir(&workspace_root, &entry.repo, &entry.branch);
   354→        let main_workspace_path = st
   355→            .workspaces_for_repo(&entry.repo)
   356→            .into_iter()
   357→            .find(|ws| ws.path.is_some())
   358→            .and_then(|ws| ws.path.as_ref().map(PathBuf::from));
   359→
   360→        match main_workspace_path {
   361→            Some(main_path) if main_path.join(".git").exists() => {
   362→                info!("Cloning from local main workspace...");
   363→                match clone::clone_from_local(&main_path, &target_dir, &entry.branch) {
   364→                    Ok(dir) => dir,
   365→                    Err(e) => {
   366→                        error!("local clone failed: {e}");
   367→                        return 1;
   368→                    }
   369→                }
   370→            }
   371→            _ => {
   372→                // Fallback: clone from remote URL
   373→                match clone::clone_workspace(
   374→                    &workspace_root,
   375→                    &entry.repo,
   376→                    &entry.url,
   377→                    &entry.branch,
   378→                ) {
   379→                    Ok(dir) => dir,
   380→                    Err(e) => {
   381→                        error!("clone failed: {e}");
   382→                        return 1;
   383→                    }
   384→                }
   385→            }
   386→        }
   387→    };
   388→
   389→    // Step 2: Handle shared files
   390→    let hints = config::load_hints(&workspace_dir).unwrap_or_default();
   391→    if let Some(ref shared_config) = hints.shared
   392→        && !shared_config.files.is_empty()
   393→        && let Ok(shared_dir) = shared::ensure_shared_dir(&entry.repo)
   394→    {
   395→        if entry.path.is_some() {
   396→            // Main workspace: ensure shared files are initialized
   397→            match shared::init_from_main(&workspace_dir, &shared_dir, &shared_config.files) {
   398→                Ok(moved) => {
   399→                    for f in &moved {
   400→                        info!("  shared: {f} → ~/.dual/shared/{}/", entry.repo);
   401→                    }
   402→                }
   403→                Err(e) => warn!("shared init failed: {e}"),
   404→            }
   405→        } else {
   406→            // Branch workspace: copy shared files
   407→            match shared::copy_to_branch(&workspace_dir, &shared_dir, &shared_config.files) {
   408→                Ok(copied) => {
   409→                    for f in &copied {
   410→                        info!("  shared: copied {f}");
   411→                    }
   412→                }
   413→                Err(e) => warn!("shared copy failed: {e}"),
   414→            }
   415→        }
   416→    }
   417→
   418→    // Step 3: Ensure container exists and is running
   419→    let is_new_container = matches!(
   420→        container::status(&container_name),
   421→        container::ContainerStatus::Missing
   422→    );
   423→    match container::status(&container_name) {
   424→        container::ContainerStatus::Missing => {
   425→            // Build image from Dockerfile if configured
   426→            let effective_image = if let Some(ref build) = hints.dockerfile {
   427→                let image_tag = format!("dual-build-{container_name}");
   428→                info!("Building image from Dockerfile...");
   429→                match container::build_image(&image_tag, &workspace_dir, build) {
   430→                    Ok(tag) => tag,
   431→                    Err(e) => {
   432→                        error!("docker build failed: {e}");
   433→                        return 1;
   434→                    }
   435→                }
   436→            } else {
   437→                hints.image.clone()
   438→            };
   439→
   440→            info!("Creating container {container_name}...");
   441→            if let Err(e) = container::create(
   442→                &container_name,
   443→                &workspace_dir,
   444→                &effective_image,
   445→                &hints.env,
   446→                &hints.anonymous_volumes,
   447→            ) {
   448→                error!("container create failed: {e}");
   449→                return 1;
   450→            }
   451→            if let Err(e) = container::start(&container_name) {
   452→                error!("container start failed: {e}");
   453→                return 1;
   454→            }
   455→        }
   456→        container::ContainerStatus::Stopped => {
   457→            info!("Starting container {container_name}...");
   458→            if let Err(e) = container::start(&container_name) {
   459→                error!("container start failed: {e}");
   460→                return 1;
   461→            }
   462→        }
   463→        container::ContainerStatus::Running => {}
   464→    }
   465→
   466→    // Step 3.5: Run setup command on new containers
   467→    if is_new_container && let Some(ref setup) = hints.setup {
   468→        info!("Running setup: {setup}");
   469→        if let Err(e) = container::exec_setup(&container_name, setup) {
   470→            error!("setup failed: {e}");
   471→            return 1;
   472→        }
   473→    }
   474→
   475→    // Step 4: Write shell RC file
   476→    let rc_path = match shell::write_rc_file(&container_name, &hints.extra_commands) {
   477→        Ok(p) => p,
   478→        Err(e) => {
   479→            error!("failed to write shell RC: {e}");
   480→            return 1;
   481→        }
   482→    };
   483→
   484→    // Step 5: Create tmux session if not alive
   485→    if !backend.is_alive(&session_name) {
   486→        let source_cmd = shell::source_file_command(&rc_path);
   487→        if let Err(e) = backend.create_session(&session_name, &workspace_dir, Some(&source_cmd)) {
   488→            error!("session creation failed: {e}");
   489→            return 1;
   490→        }
   491→
   492→        // Set session-level env vars so new panes auto-source interception
   493→        let rc_path_str = rc_path.to_string_lossy();
   494→        for (key, value) in [
   495→            ("DUAL_ACTIVE", "1"),
   496→            ("DUAL_RC_PATH", rc_path_str.as_ref()),
   497→            ("DUAL_CONTAINER", container_name.as_str()),
   498→        ] {
   499→            if let Err(e) = dual::tmux_backend::set_session_env(&session_name, key, value) {
   500→                warn!("failed to set tmux env {key}: {e}");
   501→            }
   502→        }
   503→    }
   504→
   505→    // Step 6: Attach
   506→    info!("Attaching to {session_name}...");
   507→    if let Err(e) = backend.attach(&session_name) {
   508→        error!("attach failed: {e}");
   509→        return 1;
   510→    }
   511→
   512→    0
   513→}
