   624→/// Open workspace services in the default browser.
   625→fn cmd_open(workspace: Option<String>) -> i32 {
   626→    let st = match state::load() {
   627→        Ok(s) => s,
   628→        Err(e) => {
   629→            error!("{e}");
   630→            return 1;
   631→        }
   632→    };
   633→
   634→    let url_groups = proxy::workspace_urls(&st);
   635→    if url_groups.is_empty() {
   636→        info!("No URLs configured. Add 'forwardPorts' to devcontainer.json in your repo.");
   637→        return 0;
   638→    }
   639→
   640→    // Filter by workspace if specified
   641→    let filtered: Vec<_> = match &workspace {
   642→        Some(ws) => url_groups.into_iter().filter(|(id, _)| id == ws).collect(),
   643→        None => url_groups,
   644→    };
   645→
   646→    if filtered.is_empty() {
   647→        if let Some(ws) = &workspace {
   648→            error!("no URLs for workspace '{ws}'");
   649→        }
   650→        return 1;
   651→    }
   652→
   653→    for (_, urls) in &filtered {
   654→        for url_line in urls {
   655→            // Extract the URL part (after the status icon)
   656→            let url = url_line
   657→                .trim()
   658→                .trim_start_matches('\u{25cf}')
   659→                .trim_start_matches('\u{25cb}')
   660→                .trim();
   661→            let http_url = format!("http://{url}");
   662→            #[cfg(target_os = "macos")]
   663→            let _ = std::process::Command::new("open").arg(&http_url).spawn();
   664→            #[cfg(target_os = "linux")]
   665→            let _ = std::process::Command::new("xdg-open")
   666→                .arg(&http_url)
   667→                .spawn();
   668→            info!("Opening {http_url}");
   669→        }
   670→    }
   671→
   672→    0
   673→}
