   914→/// Print workspace status grouped by repo.
   915→fn print_workspace_status(st: &state::WorkspaceState, backend: &dyn MultiplexerBackend) {
   916→    let workspace_root = st.workspace_root();
   917→
   918→    // Collect unique repo names in order of first appearance
   919→    let mut repos: Vec<String> = Vec::new();
   920→    for ws in st.all_workspaces() {
   921→        if !repos.contains(&ws.repo) {
   922→            repos.push(ws.repo.clone());
   923→        }
   924→    }
   925→
   926→    for repo in &repos {
   927→        println!("{repo}");
   928→        for ws in st.workspaces_for_repo(repo) {
   929→            let container_name = config::container_name(&ws.repo, &ws.branch);
   930→            let session_name = config::session_name(&ws.repo, &ws.branch);
   931→
   932→            let clone_exists = if ws.path.is_some() {
   933→                ws.path
   934→                    .as_ref()
   935→                    .map(|p| PathBuf::from(p).join(".git").exists())
   936→                    .unwrap_or(false)
   937→            } else {
   938→                clone::workspace_exists(&workspace_root, &ws.repo, &ws.branch)
   939→            };
   940→            let container_st = container::status(&container_name);
   941→            let tmux_alive = backend.is_alive(&session_name);
   942→
   943→            let (icon, status_text) = match (&container_st, tmux_alive) {
   944→                (container::ContainerStatus::Running, true) => {
   945→                    ("\u{25cf}", "running  (container: up, tmux: attached)")
   946→                }
   947→                (container::ContainerStatus::Running, false) => {
   948→                    ("\u{25cf}", "running  (container: up, tmux: none)")
   949→                }
   950→                (container::ContainerStatus::Stopped, true) => (
   951→                    "\u{25cb}",
   952→                    "stopped  (container: stopped, tmux: background)",
   953→                ),
   954→                (container::ContainerStatus::Stopped, false) => {
   955→                    ("\u{25cb}", "stopped  (container: stopped, tmux: none)")
   956→                }
   957→                (container::ContainerStatus::Missing, _) if clone_exists => {
   958→                    ("\u{25cb}", "stopped  (not launched)")
   959→                }
   960→                (container::ContainerStatus::Missing, _) => {
   961→                    ("\u{25cc}", "lazy     (not cloned yet)")
   962→                }
   963→            };
   964→
   965→            let branch_display = config::decode_branch(&config::encode_branch(&ws.branch));
   966→            println!("  {branch_display:<24} {icon} {status_text}");
   967→        }
   968→        println!();
   969→    }
   970→}
