   138→# Default: npm, npx, pnpm, node, python, python3, pip, pip3, curl, make
   139→extra_commands = ["cargo", "go"]
   140→
   141→# Directories to isolate with anonymous Docker volumes
   142→anonymous_volumes = ["node_modules", ".next"]
