   535→/// Destroy a workspace: tmux → container → clone.
   536→fn cmd_destroy(workspace_arg: Option<&str>, backend: &dyn MultiplexerBackend) -> i32 {
   537→    let mut st = match state::load() {
   538→        Ok(s) => s,
   539→        Err(e) => {
   540→            error!("{e}");
   541→            return 1;
   542→        }
   543→    };
   544→
   545→    // Resolve workspace: use arg if provided, otherwise auto-detect from cwd
   546→    let workspace;
   547→    let entry = if let Some(ws) = workspace_arg {
   548→        workspace = ws.to_string();
   549→        match st.resolve_workspace(ws) {
   550→            Some(e) => e.clone(),
   551→            None => {
   552→                error!("unknown workspace '{ws}'");
   553→                return 1;
   554→            }
   555→        }
   556→    } else {
   557→        match detect_workspace(&st) {
   558→            Some(e) => {
   559→                workspace = config::workspace_id(&e.repo, &e.branch);
   560→                info!("Auto-detected workspace: {workspace}");
   561→                e
   562→            }
   563→            None => {
   564→                error!("could not detect workspace from current directory");
   565→                info!("Usage: dual destroy [workspace]");
   566→                return 1;
   567→            }
   568→        }
   569→    };
   570→
   571→    let workspace_root = st.workspace_root();
   572→    let container_name = config::container_name(&entry.repo, &entry.branch);
   573→    let session_name = config::session_name(&entry.repo, &entry.branch);
   574→
   575→    // Destroy tmux session
   576→    if backend.is_alive(&session_name) {
   577→        info!("Destroying session {session_name}...");
   578→        if let Err(e) = backend.destroy(&session_name) {
   579→            warn!("session destroy failed: {e}");
   580→        }
   581→    }
   582→
   583→    // Stop and remove container
   584→    match container::status(&container_name) {
   585→        container::ContainerStatus::Running => {
   586→            info!("Stopping container {container_name}...");
   587→            if let Err(e) = container::stop(&container_name) {
   588→                warn!("container stop failed: {e}");
   589→            }
   590→            info!("Removing container {container_name}...");
   591→            if let Err(e) = container::destroy(&container_name) {
   592→                warn!("container remove failed: {e}");
   593→            }
   594→        }
   595→        container::ContainerStatus::Stopped => {
   596→            info!("Removing container {container_name}...");
   597→            if let Err(e) = container::destroy(&container_name) {
   598→                warn!("container remove failed: {e}");
   599→            }
   600→        }
   601→        container::ContainerStatus::Missing => {}
   602→    }
   603→
   604→    // Remove clone (only for non-explicit-path workspaces)
   605→    if entry.path.is_none() && clone::workspace_exists(&workspace_root, &entry.repo, &entry.branch)
   606→    {
   607→        info!("Removing clone...");
   608→        if let Err(e) = clone::remove_workspace(&workspace_root, &entry.repo, &entry.branch) {
   609→            error!("failed to remove clone: {e}");
   610→            return 1;
   611→        }
   612→    }
   613→
   614→    // Remove from state
   615→    st.remove_workspace(&entry.repo, &entry.branch);
   616→    if let Err(e) = state::save(&st) {
   617→        warn!("failed to save state: {e}");
   618→    }
   619→
   620→    info!("Workspace '{workspace}' destroyed.");
   621→    0
   622→}
