   892→/// Detect which workspace the current directory belongs to.
   893→fn detect_workspace(st: &state::WorkspaceState) -> Option<state::WorkspaceEntry> {
   894→    let cwd = std::env::current_dir().ok()?;
   895→
   896→    // Try git root first (handles being in subdirectories)
   897→    let root = std::process::Command::new("git")
   898→        .args(["rev-parse", "--show-toplevel"])
   899→        .output()
   900→        .ok()
   901→        .filter(|o| o.status.success())
   902→        .map(|o| PathBuf::from(String::from_utf8_lossy(&o.stdout).trim().to_string()))
   903→        .unwrap_or(cwd);
   904→
