   972→/// Detect git repo info from the current directory.
   973→fn detect_git_repo() -> Result<(PathBuf, String, String), String> {
   974→    // Get repo root
   975→    let root_output = std::process::Command::new("git")
   976→        .args(["rev-parse", "--show-toplevel"])
   977→        .output()
   978→        .map_err(|_| "git not found".to_string())?;
   979→    if !root_output.status.success() {
   980→        return Err("not inside a git repository".to_string());
   981→    }
   982→    let root = PathBuf::from(String::from_utf8_lossy(&root_output.stdout).trim());
   983→
   984→    // Get remote URL
   985→    let url_output = std::process::Command::new("git")
   986→        .args(["remote", "get-url", "origin"])
   987→        .output()
   988→        .map_err(|_| "git not found".to_string())?;
   989→    let url = if url_output.status.success() {
   990→        String::from_utf8_lossy(&url_output.stdout)
   991→            .trim()
   992→            .to_string()
   993→    } else {
   994→        root.to_string_lossy().to_string() // local-only repo, use path as URL
   995→    };
   996→
   997→    // Get current branch
   998→    let branch_output = std::process::Command::new("git")
   999→        .args(["rev-parse", "--abbrev-ref", "HEAD"])
  1000→        .output()
  1001→        .map_err(|_| "git not found".to_string())?;
  1002→    let branch = String::from_utf8_lossy(&branch_output.stdout)
  1003→        .trim()
  1004→        .to_string();
  1005→
  1006→    Ok((root, url, branch))
  1007→}
